import java.util.ArrayList;
import java.util.List;

public class TimeRangeBuilder {
    private static final long FETCH_DATA_DURATION = 1000; // Example duration in milliseconds

    public List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        long currentEnd = start;

        while (currentStart < end) {
            if (currentEnd - currentStart >= FETCH_DATA_DURATION) {
                timeRanges.add(new TimeRange(currentStart, currentStart + FETCH_DATA_DURATION));
                currentStart += FETCH_DATA_DURATION;
            } else {
                timeRanges.add(new TimeRange(currentStart, end));
                break;
            }
        }

        return timeRanges;
    }
}
