    if (lastDotIndex == -1) {
        return -1;
    }
    int lastSeparatorIndex = filename.lastIndexOf(File.separatorChar);
    if (lastSeparatorIndex >= lastDotIndex) {
        return -1;
    }
    return lastDotIndex;
